class MassMailFixedSource extends StyleDataDatabase{var$participant;function sql_dedicated_connection(){return new StyleDataConnection($this->participant);}}
foreach(array('active','implicit','inherited-attachment','inherited-mail')as$kind){
 mm_reset();$participant=new sql_db($host,'root',$password,$fixture,false);$factory=new MassMailFixedSource($db->inner);$factory->participant=$participant;$name=$kind==='inherited-mail'?'massmail:'.md5($fixture."\0".USERS_TABLE."\0".'1'):'attachment:'.md5($fixture."\0".ATTACHMENTS_TABLE);
 try{
  if(strpos($kind,'inherited-')===0){sd_check(phpbb_acl_rows($participant,"SELECT GET_LOCK('$name',0) n")[0]['n']==='1','Participant owns inherited lease');}
  else{sd_check($participant->sql_query($kind==='active'?'START TRANSACTION':'SET autocommit=0')&&$participant->sql_query("UPDATE fixture_groups SET group_name='Participant pending' WHERE group_id=9"),'Participant owns pending data');}
  $before=phpbb_acl_rows($participant,'SELECT CONNECTION_ID() n,@@SESSION.autocommit a');$caught=false;try{phpbb_send_mass_mail($factory,mm_request(),array(new MassMailFixtureController(),'create_mailer'));}catch(PhpbbMassMailFailure$error){$caught=true;}
  sd_check($caught&&!$mm_captured&&phpbb_acl_rows($participant,'SELECT CONNECTION_ID() n,@@SESSION.autocommit a')===$before,'Rejected participant stays open and unchanged');
  if(strpos($kind,'inherited-')===0){sd_check(phpbb_acl_rows($peer,"SELECT IS_USED_LOCK('$name') n")[0]['n']===$before[0]['n'],'Participant retains its lease');phpbb_acl_rows($participant,"SELECT RELEASE_LOCK('$name')");}
  else{sd_check(phpbb_acl_rows($participant,'SELECT group_name FROM fixture_groups WHERE group_id=9')[0]['group_name']==='Participant pending'&&$participant->sql_query('ROLLBACK'),'Participant retains its pending row and rollback');}
 }finally{$participant->sql_close();}mm_lease_free();$cases++;
